import React, { useState } from 'react';
import LandingIcon from './LandingIcon.jsx';
import { CONTACT, CONTACT_FORM_URL } from './landingContent.js';

const initialState = { name: '', email: '', phone: '', message: '' };

// Each enquiry is posted to a small Google Apps Script in the owner's own Google account (docs/contact-form-script).
// It saves the enquiry in a Google Sheet and emails the owners, so the form works even when our servers are down.
// If CONTACT_FORM_URL is not filled in yet, the form goes straight to the email / WhatsApp fallback below.
const SEND_TIMEOUT_MS = 20000;
// WhatsApp opens a chat with the first phone number, message filled in: the quickest way to reach us when the form cannot send.
const WHATSAPP_NUMBER = (CONTACT.phones[0]?.tel || '').replace(/\D/g, '');
const FAIL_MESSAGE = 'Sorry, we could not send your message. Please call or email us using the details above.';

// If sending fails, the visitor can still reach us: this opens their own email app with the message filled in.
const buildMailto = ({ name, email, phone, message }) => {
  const body = `Name: ${name}\nEmail: ${email}\nPhone: ${phone}\n\n${message}`;
  return `mailto:${CONTACT.emails.join(',')}?subject=${encodeURIComponent('Scholae enquiry')}&body=${encodeURIComponent(
    body
  )}`;
};

const buildWhatsApp = ({ name, email, phone, message }) =>
  `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
    `Scholae enquiry\nName: ${name}\nEmail: ${email}\nPhone: ${phone}\n${message}`
  )}`;

const LandingContactForm = () => {
  const [values, setValues] = useState(initialState);
  const [honey, setHoney] = useState('');
  const [status, setStatus] = useState({ type: '', message: '', mailto: '', whatsapp: '' });
  const [sending, setSending] = useState(false);

  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setSending(true);
    setStatus({ type: '', message: '', mailto: '', whatsapp: '' });
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), SEND_TIMEOUT_MS);
    try {
      if (!CONTACT_FORM_URL) {
        throw new Error('contact form address is not set');
      }
      // text/plain keeps this a "simple" request, so the browser sends it without a CORS preflight (Apps Script cannot answer one).
      const res = await fetch(CONTACT_FORM_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ ...values, website: honey }),
        signal: controller.signal,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success !== true) {
        throw new Error(data.message || 'send failed');
      }
      setStatus({ type: 'ok', message: 'Thanks for contacting us. We will reach out to you soon.' });
      setValues(initialState);
    } catch (err) {
      setStatus({ type: 'error', message: FAIL_MESSAGE, mailto: buildMailto(values), whatsapp: buildWhatsApp(values) });
    } finally {
      clearTimeout(timer);
      setSending(false);
    }
  };

  return (
    <form className="sl-form" onSubmit={handleSubmit}>
      <h3>Book a free demo</h3>
      <p>Tell us a little about your institution and we will get back to you.</p>
      <label htmlFor="sl-name">Your name</label>
      <input id="sl-name" name="name" type="text" value={values.name} onChange={handleChange} required />
      <div className="sl-form-row">
        <div>
          <label htmlFor="sl-email">Email address</label>
          <input id="sl-email" name="email" type="email" value={values.email} onChange={handleChange} required />
        </div>
        <div>
          <label htmlFor="sl-phone">Phone number</label>
          <input id="sl-phone" name="phone" type="tel" value={values.phone} onChange={handleChange} />
        </div>
      </div>
      <label htmlFor="sl-msg">How can we help?</label>
      <textarea
        id="sl-msg"
        name="message"
        rows="4"
        placeholder="Institution name, number of students, what you are looking for..."
        value={values.message}
        onChange={handleChange}
        required
      />
      {/* Honeypot: hidden from people, filled in by spam bots. The script drops submissions where it is not empty. */}
      <input
        type="text"
        name="website"
        value={honey}
        onChange={e => setHoney(e.target.value)}
        tabIndex={-1}
        autoComplete="off"
        aria-hidden="true"
        style={{ position: 'absolute', left: '-9999px', width: 1, height: 1, opacity: 0 }}
      />
      <button type="submit" className="sl-btn sl-btn-primary sl-btn-block" disabled={sending}>
        {sending ? 'Sending...' : 'Send message'} <LandingIcon name="arrow" size={18} />
      </button>
      {status.message && (
        <p className={`sl-form-status sl-form-status-${status.type}`} role="status">
          {status.message}
          {status.mailto && (
            <>
              {' '}
              <a href={status.mailto}>Send it by email instead</a>
              {status.whatsapp && (
                <>
                  {' or '}
                  <a href={status.whatsapp} target="_blank" rel="noopener noreferrer">
                    message us on WhatsApp
                  </a>
                </>
              )}
            </>
          )}
        </p>
      )}
    </form>
  );
};

export default LandingContactForm;
